&lt;/a&gt;&lt;div class=&quot;description&quot;&gt;&lt;b&gt;&lt;i&gt;Note.&lt;/b&gt; Cette page est un regroupement &lt;u&gt;non-officiel&lt;/u&gt; de dons qui agissent dans un m&#234;me cadre. R&#233;f&#233;rez-vous &#224; &lt;a class=&quot;pagelink&quot; href=&quot;Dons.html&quot; title=&quot;Les dons&quot;&gt;cette page&lt;/a&gt; pour trouver les distinctions officielles de chaque type de don.&lt;/i&gt;&lt;/div&gt;&lt;br /&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche&quot;&gt;&lt;caption&gt;Dons de magie divers&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;30%&quot;&gt;Dons&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot; WIDTH=&quot;25%&quot;&gt;Conditions&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot; WIDTH=&quot;45%&quot;&gt;Avantages&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Combat et magie &lt;/td&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Frappe-Magique.html&quot; title=&quot;Frappe magique&quot;&gt;Frappe magique&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;Capacit&#233; &#224; lancer des sorts profanes&lt;/td&gt;&lt;td&gt;+1 aux d&#233;g&#226;ts, armes consid&#233;r&#233;es comme magiques&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Magie-De-Guerre.html&quot; title=&quot;Magie de guerre&quot;&gt;Magie de guerre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;+4 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; pour incanter un sort sur la d&#233;fensive&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Concentration-Instinctive.html&quot; title=&quot;Concentration instinctive&quot;&gt;Concentration instinctive&lt;/a&gt;&lt;sup&gt;um&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Magie-De-Guerre.html&quot; title=&quot;Magie de guerre&quot;&gt;Magie de guerre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Pas de test de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; en cas de mouvement violent, bonus de +2 sur tous les autres&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre-Guerrier.html&quot; title=&quot;Pr&#234;tre guerrier&quot;&gt;Pr&#234;tre guerrier&lt;/a&gt;&lt;sup&gt;um&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;capacit&#233; &#224; lancer des sorts divins, domaine ou myst&#232;re&lt;/td&gt;&lt;td&gt;bonus +1 initiative et +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; pour incanter sur la d&#233;fensive&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Contresort&lt;/td&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Bluff-Magique.html&quot; title=&quot;Bluff magique&quot;&gt;Bluff magique&lt;/a&gt;&lt;sup&gt;um&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;5 &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences#Acquerir.html&quot; title=&quot;rang&quot;&gt;rangs&lt;/a&gt; en &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; et en &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Le personnage &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;bluffe&lt;/a&gt; les autres lanceurs de sorts, ce qui augmente le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; pour identifier ses sorts&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Contresort.html&quot; title=&quot;Science du contresort&quot;&gt;Science du contresort&lt;/a&gt;&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;Capacit&#233; &#224; &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Contresort.html&quot; title=&quot;contresort&quot;&gt;contrer un sort&lt;/a&gt; &#224; l’aide d’un autre sort de la m&#234;me &lt;a class=&quot;pagelink&quot; href=&quot;&#201;coles-De-Magie.html&quot; title=&quot;Les &#233;coles de magie du magicien&quot;&gt;&#233;cole&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Parade-De-Sorts.html&quot; title=&quot;Parade de sorts&quot;&gt;Parade de sorts&lt;/a&gt;&lt;sup&gt;APG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; 15 &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences#Acquerir.html&quot; title=&quot;rang&quot;&gt;rangs&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Contresort.html&quot; title=&quot;Science du contresort&quot;&gt;Science du contresort&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Renvoyer un sort contr&#233; vers le lanceur&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Magie divine&lt;/td&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;td&gt;&amp;emsp; &lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-Sacr&#233;e.html&quot; title=&quot;Convocation sacr&#233;e&quot;&gt;Convocation sacr&#233;e&lt;/a&gt;&lt;sup&gt;um&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Aura, &lt;i&gt;convocation de monstres&lt;/i&gt;&lt;/td&gt;&lt;td&gt;Convoque des monstres dont le sous-type d’alignement correspond &#224; celui du personnage par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Interf&#233;rence-Divine.html&quot; title=&quot;Interf&#233;rence divine&quot;&gt;Interf&#233;rence divine&lt;/a&gt;&lt;sup&gt;um&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Lanceur de sorts divins, lanceur de sorts niveau 10&lt;/td&gt;&lt;td&gt;Sacrifie un sort pour obliger un ennemi &#224; refaire un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d’attaque&lt;/a&gt; r&#233;ussi contre un alli&#233;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Th&#233;urgie.html&quot; title=&quot;Th&#233;urgie&quot;&gt;Th&#233;urgie&lt;/a&gt;&lt;sup&gt;um&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;Sag&quot;&gt;Sag&lt;/a&gt; 13, &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;Int&quot;&gt;Int&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Cha&quot;&gt;Cha&lt;/a&gt; 13, capacit&#233; &#224; lancer des sorts profanes et divins de niveau 1&lt;/td&gt;&lt;td&gt;Am&#233;liore les sorts profanes avec de l’&#233;nergie divine et inversement&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Percer la R&#233;sistance &#224; la Magie&lt;/td&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;td&gt;&amp;emsp; &lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Efficacit&#233;-Des-Sorts-Accrue.html&quot; title=&quot;Efficacit&#233; des sorts accrue&quot;&gt;Efficacit&#233; des sorts accrue&lt;/a&gt;&lt;/td&gt;&lt;td&gt;-&lt;/td&gt;&lt;td&gt;+2 au &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Rm.html&quot; title=&quot;test de niveau de lanceur de sorts&quot;&gt;test de niveau de lanceur de sorts&lt;/a&gt; pour vaincre la &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance &#224; la magie&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Efficacit&#233;-Des-Sorts-Accrue-Sup&#233;rieure.html&quot; title=&quot;Efficacit&#233; des sorts accrue sup&#233;rieure&quot;&gt;Efficacit&#233; des sorts accrue sup&#233;rieure&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Efficacit&#233;-Des-Sorts-Accrue.html&quot; title=&quot;Efficacit&#233; des sorts accrue&quot;&gt;Efficacit&#233; des sorts accrue&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+2 au &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Rm.html&quot; title=&quot;test de niveau de lanceur de sorts&quot;&gt;test de niveau de lanceur de sorts&lt;/a&gt; pour vaincre la &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance &#224; la magie&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Pouvoirs magiques&lt;/td&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;td&gt;&amp;emsp; &lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Expertise-Magique-Mineure.html&quot; title=&quot;Expertise magique mineure&quot;&gt;Expertise magique mineure&lt;/a&gt;&lt;sup&gt;APG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Capacit&#233;s de lancer des sorts du 4e niveau&lt;/td&gt;&lt;td&gt;Lancer un sort de 1er niveau comme &lt;a class=&quot;pagelink&quot; href=&quot;Capacit&#233;s-Sp&#233;ciales#Types.html&quot; title=&quot;pouvoir magique&quot;&gt;pouvoir magique&lt;/a&gt; 2/jour&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Expertise-Magique-Majeure.html&quot; title=&quot;Expertise magique majeure&quot;&gt;Expertise magique majeure&lt;/a&gt;&lt;sup&gt;APG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Expertise-Magique-Mineure.html&quot; title=&quot;Expertise magique mineure&quot;&gt;Expertise magique mineure&lt;/a&gt;, sorts de niveau 9&lt;/td&gt;&lt;td&gt;Lancer un sort de niveau inf&#233;rieur ou &#233;gal &#224; 5 comme &lt;a class=&quot;pagelink&quot; href=&quot;Capacit&#233;s-Sp&#233;ciales#Types.html&quot; title=&quot;pouvoir magique&quot;&gt;pouvoir magique&lt;/a&gt; 2/jour&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Transformation de sorts&lt;/td&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;td&gt;&amp;emsp; &lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Attaque-Magique.html&quot; title=&quot;Attaque magique&quot;&gt;Attaque magique&lt;/a&gt;&lt;sup&gt;APG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Lanceur de sorts profanes, &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; 10&lt;/td&gt;&lt;td&gt;Sacrifier un sort, gagner une attaque de rayon&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Magique.html&quot; title=&quot;Bouclier magique&quot;&gt;Bouclier magique&lt;/a&gt;&lt;sup&gt;APG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Lanceur de sorts profanes, &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; 10&lt;/td&gt;&lt;td&gt;Sacrifier un sort, gagner un bonus de parade &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;
&lt;i&gt;Les dons marqu&#233;s de &lt;sup&gt;APG&lt;/sup&gt; proviennent du Manuel des Joueurs - R&#232;gles Avanc&#233;es.&lt;/i&gt; &lt;br/&gt;
&lt;i&gt;Les dons marqu&#233; de &lt;sup&gt;uc&lt;/sup&gt; proviennent de l&#39;Art de la Guerre.&lt;/i&gt; &lt;br/&gt;
&lt;i&gt;Les dons marqu&#233;s de &lt;sup&gt;um&lt;/sup&gt; proviennent de l&#39;Art de la Magie.&lt;/i&gt;
